function trap(height) {
  let water = 0;
  for (let i = 0; i < height.length; i++) {
    let leftMax = 0;
    let rightMax = 0;
    for (let j = 0; j <= i; j++) leftMax = Math.max(leftMax, height[j]);              // tallest at or left of i
    for (let j = i; j < height.length; j++) rightMax = Math.max(rightMax, height[j]); // tallest at or right of i
