function trap(height) {
  const stack = [];                // indexes of walls; heights decrease upward
  let water = 0;
  for (let i = 0; i < height.length; i++) {
    while (stack.length > 0 && height[i] > height[stack[stack.length - 1]]) {
      const bottom = stack.pop();
      if (stack.length === 0) break;              // no wall on the left
      const left = stack[stack.length - 1];
      const width = i - left - 1;
      const depth = Math.min(height[left], height[i]) - height[bottom];
      water += width * depth;                      // one horizontal layer
    }
    stack.push(i);
  }
  return water;
}

public int trap(int[] height) {
    Deque<Integer> stack = new ArrayDeque<>();   // indexes of walls; heights decrease upward
    int water = 0;
    for (int i = 0; i < height.length; i++) {
        while (!stack.isEmpty() && height[i] > height[stack.peek()]) {
            int bottom = stack.pop();
            if (stack.isEmpty()) break;          // no wall on the left
            int left = stack.peek();
            int width = i - left - 1;
            int depth = Math.min(height[left], height[i]) - height[bottom];
            water += width * depth;              // one horizontal layer
        }
        stack.push(i);
    }
    return water;
}

int trap(vector<int>& height) {
    stack<int> st;                       // indexes of walls; heights decrease upward
    int water = 0;
    for (int i = 0; i < (int)height.size(); i++) {
        while (!st.empty() && height[i] > height[st.top()]) {
            int bottom = st.top();
            st.pop();
            if (st.empty()) break;           // no wall on the left
            int left = st.top();
            int width = i - left - 1;
            int depth = min(height[left], height[i]) - height[bottom];
            water += width * depth;          // one horizontal layer
        }
        st.push(i);
    }
    return water;
}

function trap(height) {
  let left = 0, right = height.length - 1;
  let leftMax = 0, rightMax = 0;
  let water = 0;
  while (left < right) {
    if (height[left] < height[right]) {
      leftMax = Math.max(leftMax, height[left]);
      water += leftMax - height[left];      // the right side is surely taller
      left++;
    } else {
      rightMax = Math.max(rightMax, height[right]);
      water += rightMax - height[right];    // the left side is surely taller
      right--;
    }
  }
  return water;
}

